using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Linq;
using System.Windows.Forms;

namespace DeskShift {
    internal sealed class FloatingLauncher : IDisposable {
        readonly Library library;readonly Func<Wallpaper,Image> image;readonly Action<Wallpaper> select;readonly OrbWindow orb;WallpaperPicker picker;bool suspended;
        internal FloatingLauncher(Library data,Func<Wallpaper,Image> preview,Action<Wallpaper> choose,Action open,Action disable){library=data;image=preview;select=choose;orb=new OrbWindow();orb.Pressed+=TogglePicker;orb.PositionSaved+=point=>{library.State.OrbX=point.X;library.State.OrbY=point.Y;library.State.HasOrbPosition=true;library.Save();};var menu=new ContextMenuStrip();menu.Items.Add("打开 DeskShift",null,(s,e)=>open());menu.Items.Add("隐藏悬浮球",null,(s,e)=>disable());orb.ContextMenuStrip=menu;var area=Screen.PrimaryScreen.WorkingArea;orb.Location=OrbWindow.Clamp(new Point(data.State.HasOrbPosition?data.State.OrbX:area.Right-84,data.State.HasOrbPosition?data.State.OrbY:area.Top+area.Height/2),orb.Size);Refresh();}
        internal void Refresh(){var palette=library.State.ActivePalette;var active=library.State.Wallpapers.FirstOrDefault(w=>w.Id==library.State.ActiveId)??library.State.Wallpapers.FirstOrDefault();orb.Accent=Palette.ColorOf(palette==null?(active==null?"#587A68":active.Palette.Accent):palette.Accent);orb.Invalidate();if(library.State.ShowFloatingOrb && !suspended){orb.Location=OrbWindow.Clamp(orb.Location,orb.Size);if(!orb.Visible)orb.Show();}else{ClosePicker();orb.Hide();}}
        internal void Suspend(bool value){suspended=value;Refresh();}
        void TogglePicker(){if(suspended)return;if(picker!=null && !picker.IsDisposed && picker.Visible){ClosePicker();return;}ClosePicker();picker=new WallpaperPicker(library,image,w=>{ClosePicker();select(w);});var area=Screen.FromControl(orb).WorkingArea;int x=orb.Left-picker.Width-12;if(x<area.Left+8)x=orb.Right+12;picker.Location=new Point(Math.Max(area.Left+8,Math.Min(x,area.Right-picker.Width-8)),Math.Max(area.Top+8,Math.Min(orb.Top-picker.Height/2+orb.Height/2,area.Bottom-picker.Height-8)));picker.Show();picker.Activate();}
        void ClosePicker(){if(picker!=null){picker.Dispose();picker=null;}}
        public void Dispose(){ClosePicker();if(orb.ContextMenuStrip!=null)orb.ContextMenuStrip.Dispose();orb.Dispose();}
    }
    internal sealed class OrbWindow : Form {
        internal Color Accent=Color.FromArgb(88,122,104);internal event Action Pressed;internal event Action<Point> PositionSaved;Point down,origin;bool tracking,dragging,hover;
        internal OrbWindow(){FormBorderStyle=FormBorderStyle.None;ShowInTaskbar=false;TopMost=true;StartPosition=FormStartPosition.Manual;AutoScaleMode=AutoScaleMode.None;ClientSize=new Size(60,60);DoubleBuffered=true;Cursor=Cursors.Hand;AccessibleName="DeskShift 悬浮球，点击选择壁纸";using(var path=new GraphicsPath()){path.AddEllipse(1,1,58,58);Region=new Region(path);}BackColor=Color.FromArgb(246,249,246);}
        protected override bool ShowWithoutActivation{get{return true;}}
        protected override CreateParams CreateParams{get{var p=base.CreateParams;p.ExStyle|=0x08000000|0x80;return p;}}
        protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(BackColor);using(var brush=new LinearGradientBrush(ClientRectangle,Color.White,Palette.Mix(Accent,Color.White,.86),50))g.FillEllipse(brush,2,2,55,55);using(var pen=new Pen(Color.FromArgb(hover?150:65,Accent),hover?2:1))g.DrawEllipse(pen,3,3,53,53);using(var pen=new Pen(Palette.Mix(Accent,Color.FromArgb(35,50,44),.25),2.1f)){using(var path=Interface.Round(new RectangleF(16,17,27,22),5))g.DrawPath(pen,path);g.DrawLines(pen,new[]{new Point(20,33),new Point(26,26),new Point(31,31),new Point(36,26),new Point(40,31)});}using(var brush=new SolidBrush(Accent))g.FillEllipse(brush,33,21,4,4);using(var pen=new Pen(Color.FromArgb(120,Accent),2))g.DrawLine(pen,24,44,36,44);}
        protected override void OnMouseEnter(EventArgs e){base.OnMouseEnter(e);hover=true;Invalidate();}
        protected override void OnMouseLeave(EventArgs e){base.OnMouseLeave(e);hover=false;Invalidate();}
        protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button!=MouseButtons.Left)return;tracking=true;dragging=false;down=Cursor.Position;origin=Location;Capture=true;}
        protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(!tracking)return;var now=Cursor.Position;int dx=now.X-down.X,dy=now.Y-down.Y;if(Math.Abs(dx)>SystemInformation.DragSize.Width/2 || Math.Abs(dy)>SystemInformation.DragSize.Height/2)dragging=true;if(dragging)Location=new Point(origin.X+dx,origin.Y+dy);}
        protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);if(!tracking || e.Button!=MouseButtons.Left)return;tracking=false;Capture=false;if(dragging){Location=Clamp(Location,Size);if(PositionSaved!=null)PositionSaved(Location);}else if(Pressed!=null)Pressed();}
        protected override void OnMouseCaptureChanged(EventArgs e){base.OnMouseCaptureChanged(e);if(!Capture)tracking=false;}
        internal static Point Clamp(Point location,Size size){var area=Screen.FromRectangle(new Rectangle(location,size)).WorkingArea;return new Point(Math.Max(area.Left+8,Math.Min(location.X,area.Right-size.Width-8)),Math.Max(area.Top+8,Math.Min(location.Y,area.Bottom-size.Height-8)));}
    }
    internal sealed class WallpaperPicker : Form {
        protected override CreateParams CreateParams{get{var p=base.CreateParams;p.ClassStyle|=0x20000;p.ExStyle|=0x80;return p;}}
        internal WallpaperPicker(Library library,Func<Wallpaper,Image> image,Action<Wallpaper> choose){FormBorderStyle=FormBorderStyle.None;ShowInTaskbar=false;TopMost=true;StartPosition=FormStartPosition.Manual;AutoScaleMode=AutoScaleMode.None;BackColor=Color.FromArgb(246,248,247);Font=new Font("Microsoft YaHei UI",9);ClientSize=new Size(360,Math.Min(440,96+Math.Max(1,library.State.Wallpapers.Count)*82));using(var path=Interface.Round(new RectangleF(0,0,Width,Height),18))Region=new Region(path);DoubleBuffered=true;
            Controls.Add(new Label{Text="挑选一张壁纸",Font=new Font(Font.FontFamily,13,FontStyle.Bold),ForeColor=Color.FromArgb(36,52,44),Bounds=new Rectangle(20,17,260,30)});Controls.Add(new Label{Text="让桌面换一种心情",ForeColor=Color.FromArgb(120,132,124),Bounds=new Rectangle(21,50,270,24)});var close=new SoftButton{Text="×",Bounds=new Rectangle(310,18,30,28),BackColor=BackColor,ForeColor=Color.Gray};close.Click+=(s,e)=>Hide();Controls.Add(close);
            var list=new FlowLayoutPanel{Bounds=new Rectangle(12,82,336,Height-94),AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,BackColor=BackColor};Controls.Add(list);foreach(var wallpaper in library.State.Wallpapers){var target=wallpaper;var tile=new PickerTile(wallpaper,image(wallpaper),wallpaper.Id==library.State.ActiveId){Margin=new Padding(0,0,0,8)};tile.Click+=(s,e)=>choose(target);list.Controls.Add(tile);}if(library.State.Wallpapers.Count==0)list.Controls.Add(new Label{Text="请先在主窗口添加壁纸。",AutoSize=true});Deactivate+=(s,e)=>Hide();}
        protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var path=Interface.Round(new RectangleF(1,1,Width-3,Height-3),18))using(var pen=new Pen(Color.FromArgb(218,226,220)))e.Graphics.DrawPath(pen,path);}
        protected override bool ProcessCmdKey(ref Message msg,Keys keyData){if(keyData==Keys.Escape){Hide();return true;}return base.ProcessCmdKey(ref msg,keyData);}
    }
    internal sealed class PickerTile : Control {
        readonly Wallpaper wallpaper;readonly bool active;readonly Bitmap thumb;bool hover;
        internal PickerTile(Wallpaper item,Image preview,bool selected){wallpaper=item;active=selected;Size=new Size(312,74);DoubleBuffered=true;Cursor=Cursors.Hand;AccessibleName=item.Name+(active?"，正在使用":"，点击切换");thumb=new Bitmap(94,54);using(var g=Graphics.FromImage(thumb)){g.InterpolationMode=InterpolationMode.HighQualityBicubic;float scale=Math.Max(94f/preview.Width,54f/preview.Height);g.DrawImage(preview,(94-preview.Width*scale)/2,(54-preview.Height*scale)/2,preview.Width*scale,preview.Height*scale);}}
        protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(Parent==null?Color.FromArgb(246,248,247):Parent.BackColor);using(var path=Interface.Round(new RectangleF(1,1,Width-3,Height-3),12))using(var brush=new SolidBrush(active?Color.FromArgb(226,237,229):hover?Color.FromArgb(235,241,237):Color.White))g.FillPath(brush,path);var state=g.Save();using(var path=Interface.Round(new RectangleF(10,10,94,54),7)){g.SetClip(path);g.DrawImageUnscaled(thumb,10,10);}g.Restore(state);using(var font=new Font("Microsoft YaHei UI",9,FontStyle.Bold))TextRenderer.DrawText(g,wallpaper.Name,font,new Rectangle(117,14,176,25),Color.FromArgb(43,60,51),TextFormatFlags.EndEllipsis|TextFormatFlags.SingleLine);for(int i=0;i<Math.Min(5,wallpaper.Palette.Swatches.Length);i++)using(var brush=new SolidBrush(Palette.ColorOf(wallpaper.Palette.Swatches[i])))g.FillEllipse(brush,119+i*15,47,8,8);if(active)using(var font=new Font("Microsoft YaHei UI",8))TextRenderer.DrawText(g,"使用中 ✓",font,new Rectangle(218,43,82,23),Color.FromArgb(76,110,88),TextFormatFlags.Right);}
        protected override void OnMouseEnter(EventArgs e){base.OnMouseEnter(e);hover=true;Invalidate();}
        protected override void OnMouseLeave(EventArgs e){base.OnMouseLeave(e);hover=false;Invalidate();}
        protected override void Dispose(bool disposing){if(disposing)thumb.Dispose();base.Dispose(disposing);}
    }
}
